"""Write eval/results.md from the JSON results (CLAUDE.md §12: generated by script, never hand-edited).
Inputs: eval/transcription.json · eval/planning.json · eval/persistence.json · eval/results.json (call extraction, eval/run_eval.py)
Run: python -m eval.report"""
import json
from datetime import datetime, timedelta, timezone
from pathlib import Path

E = Path(__file__).parent
IST = timezone(timedelta(hours=5, minutes=30))


def load(name: str):
    p = E / name
    return json.loads(p.read_text(encoding="utf-8")) if p.exists() else None


def pct(a: float, b: float) -> str:
    return f"{a}/{b} ({(100 * a / b) if b else 0:.0f}%)"


def main() -> None:
    L = [f"# Chinku — evidence (generated by `python -m eval.report` — do not edit)", "",
         f"Generated {datetime.now(IST):%a %d %b %Y, %H:%M} IST · brain model `gpt-5.5` (same model for Chinku and every baseline)", ""]

    t = load("transcription.json")
    if t:
        n = len(t)
        c_err = sum(r["chinku"]["errors"] for r in t); b_err = sum(r["baseline"]["errors"] for r in t)
        words = sum(r["truth_words"] for r in t)
        c_h = sum(r["chinku"]["hallucinated"] for r in t); b_h = sum(r["baseline"]["hallucinated"] for r in t)
        c_exact = sum(r["chinku"]["errors"] == 0 for r in t); b_exact = sum(r["baseline"]["errors"] == 0 for r in t)
        te = [r for r in t if r["page"].startswith(("p09", "p10"))]
        L += ["## 1. Exact transcription (photo → text)", "",
              f"{n} pages with typed ground truth ({words} words). **SIMULATED inputs:** handwriting-style fonts with rotation, blur and paper "
              "noise (Telugu pages drawn by Chrome for correct letter joining) — not real handwriting yet.",
              "Baseline = the same model with one plain prompt: *\"Read this image.\"*", "",
              "| | Chinku (`transcribe_image`) | Baseline |", "|---|---|---|",
              f"| Word error rate (all pages) | **{c_err / words:.1%}** ({c_err} errors) | {b_err / words:.1%} ({b_err} errors) |",
              f"| Pages copied exactly (0 errors) | **{c_exact}/{n}** | {b_exact}/{n} |",
              f"| Words added that are not on the page | **{c_h}** | {b_h} |",
              f"| Telugu pages: errors | {sum(r['chinku']['errors'] for r in te)} | {sum(r['baseline']['errors'] for r in te)} |", "",
              "How to read this: most baseline errors are **added text** (\"The image reads:\", an English translation of Telugu pages, markdown "
              "bullets) rather than misread words — still wrong for an exact copy that is emailed to someone. Chinku's remaining errors are on the "
              "Telugu note: it changed a word (మాత్ర → మాత్రం) and \"corrected\" a spelling (మర్చిపోవద్దు → మరిచిపోవద్దు), which its rules forbid — "
              "a known limit.", "", "| Page | Chinku WER | Baseline WER | Chinku added words | Baseline added words |", "|---|---|---|---|---|"]
        L += [f"| {r['page']} | {r['chinku']['wer']:.3f} | {r['baseline']['wer']:.3f} | {', '.join(r['chinku']['hallucinated_words']) or '—'} | "
              f"{', '.join(r['baseline']['hallucinated_words'][:6]) or '—'} |" for r in t]
        L.append("")

    p = load("planning.json")
    if p:
        n = p["n"]
        L += ["## 2. Planning (request → steps)", "",
              f"{n} requests (English, Telugu, Hindi, Telugu-English mix; single and multi-step) through the real planner. Run {p['run_at']}.", "",
              "| Metric | Result |", "|---|---|",
              f"| Correct steps, in order | **{pct(p['steps_correct'], n)}** |",
              f"| Correct key fields (recipient, time, language, category, priority…) | **{pct(p['fields_correct'], n)}** |",
              f"| **Wrong-action rate** (a plan that emails / calls / adds to cart without being asked) | **{pct(p['wrong_action_plans'], n)}** (target 0) |", "",
              "Caveat: the requests were written by the builder and the planner instructions were tuned on similar wording — this is not a "
              "fresh hold-out set. Independently of the plan, code enforces approval before any email, call, cart change or reminder call.", "",
              "| Lang | Request | Expected | Planned | OK |", "|---|---|---|---|---|"]
        L += [f"| {r['lang']} | {r['request'][:70]} | {' → '.join(r.get('expected') or []) or '(ask / answer)'} | "
              f"{' → '.join(r.get('got') or []) or ('asks: ' + (r.get('clarifying') or '')[:40] if r.get('clarifying') else '—')} | "
              f"{'✅' if r['steps_ok'] and r['fields_ok'] else '❌'}{' ⚠️' if r['wrong_actions'] else ''} |" for r in p["rows"]]
        L.append("")

    c = load("results.json")
    if c:
        s = c["summary"]["ALL"]
        L += ["## 3. Call extraction (phone call → facts with evidence)", "",
              f"{s['cases']} calls (5 real, 7 scripted) · baseline = *\"{c.get('baseline_prompt', 'Summarise this call')}\"* (from `eval/run_eval.py`).", "",
              "| | Chinku | Baseline |", "|---|---|---|",
              f"| Field accuracy | {pct(s['chinku']['correct'], s['chinku']['fields'])} | {pct(s['baseline']['correct'], s['baseline']['fields'])} |",
              f"| **Wrong-confirmed** (vague / refused / unstated reported as firm fact) | **{pct(s['chinku']['wrong_confirmed'], s['chinku']['not_firm_fields'])}** | "
              f"{pct(s['baseline']['wrong_confirmed'], s['baseline']['not_firm_fields'])} |", "",
              "Honest result: no accuracy win on field values; the gain is in not reporting tentative answers as confirmed. Money is computed in "
              "code (e.g. dealer ₹714/bag × 50 = ₹35,700).", ""]

    ps = load("persistence.json")
    if ps:
        L += ["## 4. Persistence (restart mid-task)", "",
              f"Live server, {ps['run_at']}: a pending email approval was created, the server process was restarted "
              f"(back in {ps['back_after_s']} s). Pending approval after restart: **{'yes — same task' if ps['same_task'] else 'NO'}** "
              f"(`{ps['task_id']}`). The test then answered \"no\", so nothing was sent.", ""]

    rg = load("regression.json")
    if rg:
        L += ["## 5. Live feature regression (every feature, real services)", "",
              f"Run {rg['run_at']} on the live server (`python -m scripts.regression`): real planner, OpenAI, web search, Kiwi.com, Swiggy, "
              "OpenStreetMap and DynamoDB under a test identity. Anything that would leave the app was answered \"no\" at the approval step "
              "(one email went to the owner's own inbox).", "",
              f"**{rg['passed']}/{rg['total']} passed**", "", "| Feature | Result | Observed |", "|---|---|---|"]
        L += [f"| {r['case']} | {'✅' if r['ok'] else '❌'} | {r['note'][:150]} |" for r in rg["results"]]
        L.append("")

    L += ["## Not measured yet", "", "- Real handwritten pages (only font pages so far).",
          "- Voice-note accuracy on real recordings (Telugu / English / mixed).",
          "- Official-domain rate of complaint contacts over 10 brands (only spot checks so far: Bajaj ✅).", ""]
    (E / "results.md").write_text("\n".join(L), encoding="utf-8")
    print("wrote", E / "results.md")


if __name__ == "__main__":
    main()
